settings.custom_css:
selector { flex: none; width: auto; --width: auto; min-width: 110px; }
@media (max-width: 1024px) { selector { min-width: 88px; } }
@media (max-width: 767px) { selector { min-width: 64px; } }
selector .elementor-shortcode { margin: 0; }
/* Rango de días («28–29»): más pequeño, como en el prototipo */
selector .maloka-rango { font-size: 0.7em; }

selector { font: 700 56px/1 Montserrat, sans-serif; letter-spacing: -0.03em; color: #231B2B; white-space: nowrap; }
@media (max-width: 1024px) { selector { font-size: 40px; } }
@media (max-width: 767px) { selector { font-size: 36px; } }

selector { width: 120px; flex: none; }
selector img { width: 100%; aspect-ratio: 3 / 4; object-fit: cover; display: block; background: #3A3242; }
@media (max-width: 1024px) { selector { width: 80px; } }
@media (max-width: 767px) { selector { display: none; } }

selector details summary { display: inline-flex; align-items: center; gap: 6px; font: 700 14px/1.3 Montserrat, sans-serif; color: #231B2B; cursor: pointer; list-style: none; border-bottom: 2px solid currentColor; padding-bottom: 1px; }
selector details summary::-webkit-details-marker { display: none; }
selector details summary::after { content: "⌄"; font-size: 16px; line-height: 1; transition: transform .15s; }
selector details[open] summary::after { transform: rotate(180deg); }
selector details div { margin-top: 10px; font: 400 15px/1.6 Montserrat, sans-serif; color: #231B2B; max-width: 64ch; }
selector details p { margin: 0 0 8px; }
selector summary:focus-visible { outline: 3px solid #6B5BD6; outline-offset: 2px; }

selector { flex: none; }
@media (max-width: 1024px) { selector { width: auto; flex-basis: 100%; padding-left: 216px; } }
@media (max-width: 767px) { selector { padding-left: 80px; } }

selector .maloka-evento-boton { display: inline-flex; gap: 6px; font: 700 16px/1.3 Montserrat, sans-serif; color: #231B2B; border-bottom: 2px solid currentColor; padding-bottom: 2px; }
selector .maloka-evento-boton:hover { color: #6B5BD6; }
selector .screen-reader-text { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
